201	/// The system prompt a prompt sent in `mode` is given, naming the code and
202	/// spec locations set in the project's `piton.config.pi`.
203	pub fn system_prompt(mode: SendMode, project_dir: &Path) -> Result<String> {
204	    let code = config_value(project_dir, "codeRoot")?;
205	    let spec = config_value(project_dir, "root")?;
206	    Ok(match mode {
207	        SendMode::Code => format!(
208	            "We're working on the code located in {code}. Don't edit the spec located in {spec}."
209	        ),
210	        SendMode::Both => format!(
211	            "We're working on both the code located in {code} and the spec located in {spec}. Edit both of them."
212	        ),
213	        SendMode::Spec => format!(
214	            "We're working on the spec located in {spec}. Don't edit the code located in {code}."
215	        ),
216	    })
217	}
218	
219	/// The path the chat input's unsent text is presented to `piton lsp` under.
220	/// Nothing is written there. It sits inside the spec root because `piton lsp`
221	/// only resolves imports, and offers auto-imports, for documents under it.
222	pub fn draft_path(project_dir: &Path) -> PathBuf {
223	    let spec_root = spec_root(project_dir).unwrap_or_default();
224	    project_dir.join(spec_root).join(".suspense-draft.pi")
225	}
226	
227	/// The project's prompt history directory.
228	pub fn history_dir(project_dir: &Path) -> PathBuf {
229	    project_dir.join(APP_DIR).join(HISTORY_DIR)
230	}
231	
